sys_script_fix.script:
var pdfDraftRec = new GlideRecord('pdf_draft');
pdfDraftRec.addQuery('active', 'true');
pdfDraftRec.query();

var hrCoreUtils = new hr_CoreUtils();
while (pdfDraftRec.next()) {
    var caseId = "";
    if (hrCoreUtils.isCase(pdfDraftRec.table) && pdfDraftRec.document.active)
        caseId = pdfDraftRec.document;
    else if (pdfDraftRec.table == hr.TABLE_TASK && pdfDraftRec.document.parent.active)
        caseId = pdfDraftRec.document.parent;
    else
        continue;

    var attachmentRec = new GlideRecord('sys_attachment');
    attachmentRec.addQuery('table_name', 'pdf_draft');
    attachmentRec.addQuery('table_sys_id', pdfDraftRec.sys_id);
    attachmentRec.query();
    if (attachmentRec.next()) {
        var caseRec = new GlideRecord('sn_hr_core_case');
        if (caseRec.get(caseId)) {
            caseRec.setValue('sn_esign_document', attachmentRec.getUniqueValue());
            caseRec.update();
        }
    }
}
